-- =====================================================================
-- Richwell product options seed (2026-11-11)
-- Suggested choices shown when an item is added to an order, e.g.
-- BANGSILOG -> Milkfish (bangus): Regular / Crispy, Rice: Garlic rice / Plain rice,
-- Egg: Sunny side up / Over easy / Scrambled / Well done.
-- 261 products, 659 option groups, plus
-- 42 category defaults (rows keyed "CAT:<category>") used by any
-- product that has no groups of its own, e.g. items added later in Product
-- List. Only choices that differ from the default are printed on the ticket.
-- Re-running replaces the Richwell rows (edits made in Product List >
-- Options are lost), so treat it as an initial seed.
-- =====================================================================

CREATE TABLE IF NOT EXISTS `tbl_pos_product_options` (
  `ID` INT NOT NULL AUTO_INCREMENT,
  `category_code` VARCHAR(100) NOT NULL,
  `unit_code` VARCHAR(100) NOT NULL,
  `product_id` VARCHAR(100) NOT NULL,
  `group_name` VARCHAR(60) NOT NULL,
  `select_type` VARCHAR(10) NOT NULL DEFAULT 'single',
  `default_option` VARCHAR(60) NULL,
  `options_json` TEXT NOT NULL,
  `sort_order` INT NOT NULL DEFAULT 0,
  `status` VARCHAR(20) NOT NULL DEFAULT 'Active',
  `date_recorded` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `date_updated` DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`ID`),
  KEY `idx_pos_product_options_product` (`product_id`, `sort_order`),
  KEY `idx_pos_product_options_scope` (`category_code`, `unit_code`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

START TRANSACTION;

DELETE FROM tbl_pos_product_options WHERE category_code = 'Richwell' AND unit_code = 'BU-24cae516f663';


COMMIT;

SELECT SUM(product_id NOT LIKE 'CAT:%') AS product_groups, SUM(product_id LIKE 'CAT:%') AS category_default_groups,
       COUNT(DISTINCT CASE WHEN product_id NOT LIKE 'CAT:%' THEN product_id END) AS products_with_options
FROM tbl_pos_product_options WHERE unit_code = 'BU-24cae516f663';
